func suggestedEzMeCategory(_ name:String,context:String="")->String {
 let value=(name+" "+context).lowercased()
 let groups:[(String,[String])]=[
  ("Finance & Billing",["invoice","bill","payment","receipt","expense","tax","account","purchase order","payroll","budget"]),
  ("Sales & CRM",["customer","client","sales","lead","quote","quotation","proposal","vendor","supplier"]),
  ("HR & People",["employee","candidate","appointment","offer letter","recruit","people","staff","onboard"]),
  ("Legal & Agreements",["agreement","contract","nda","legal","policy","compliance"]),
  ("Marketing",["marketing","campaign","social","seo","brand","content plan"]),
  ("Creative & Media",["image","photo","video","audio","media","gif","design","creative"]),
  ("Operations",["inventory","order","delivery","project","task","operations","workflow"]),
  ("Productivity",["writing","letter","email","note","summary","document","report"]),
  ("Collections & Data",["collection builder","collection","directory","catalog","database","contacts","products","services"])
 ]
 return groups.first(where:{_,terms in terms.contains(where:{value.contains($0)})})?.0 ?? "Utilities"
}
