    ScrollView{LazyVStack(spacing:4){ForEach(filteredCollectionNames,id:\.self){name in let system=builtInCollections.contains(where:{$0.caseInsensitiveCompare(name) == .orderedSame});Button{selected=name;query=""}label:{HStack(spacing:9){Image(systemName:db.isCollectionHidden(name) ? "eye.slash":collectionSymbol(name)).foregroundStyle(collectionAccent(name)).frame(width:22);VStack(alignment:.leading,spacing:2){Text(name).font(.system(size:14,weight:.semibold)).lineLimit(1);Text(collectionCategory(name,definition:db.collectionDefinitions.first(where:{$0.name.caseInsensitiveCompare(name) == .orderedSame}))).font(.system(size:9,weight:system ? .bold:.medium)).foregroundStyle(system ? collectionAccent(name):.secondary).lineLimit(1)};Spacer(minLength:2);Text("\(shortcutCount(in:name))").font(.caption.weight(.semibold)).foregroundStyle(.secondary)}.padding(9).frame(maxWidth:.infinity,alignment:.leading).background(selected.caseInsensitiveCompare(name) == .orderedSame ? collectionAccent(name).opacity(system ? 0.14:0.10):.clear,in:RoundedRectangle(cornerRadius:10)).overlay(RoundedRectangle(cornerRadius:10).stroke(system ? collectionAccent(name).opacity(0.16):.clear,lineWidth:1))}.buttonStyle(.plain)}}}
