            ForEach(Array(clip.files.prefix(3)),id:\.self) { path in MediaPreview(path:path).frame(width:48,height:48) }
            if clip.files.count>3 { Text("+\(clip.files.count-3)").font(.caption.bold()).foregroundStyle(.secondary) }
           }.frame(height:56)
