          VStack(alignment:.leading,spacing:4) { Text(clip.name).font(.system(size:17,weight:.bold,design:.rounded));Text(collectionCategory(clip.allGroups.first ?? selected,definition:db.collectionDefinitions.first(where:{$0.name.caseInsensitiveCompare(clip.allGroups.first ?? selected) == .orderedSame}))).font(.system(size:10,weight:.medium)).foregroundStyle(.secondary);Text(clip.text.isEmpty ? "\(clip.files.count) attachment(s)":clip.text).font(.subheadline).foregroundStyle(.secondary).lineLimit(2) }
          Spacer()
