 }
 private var canRenameSelectedCollection:Bool{selected != "All collections" && !builtInCollections.contains(where:{$0.caseInsensitiveCompare(selected) == .orderedSame})}
 private var selectedPageIsSelected:Bool{!pageShortcuts.isEmpty && pageShortcuts.allSatisfy{selectedShortcutIDs.contains($0.id)}}
 private func toggleCurrentPageSelection(){let ids=Set(pageShortcuts.map{$0.id});if ids.isSubset(of:selectedShortcutIDs){selectedShortcutIDs.subtract(ids)}else{selectedShortcutIDs.formUnion(ids)}}
