failures+=1;continue};do{var request=URLRequest(url:url);request.timeoutInterval=120;let(temp,response)=try await URLSession.shared.download(for:request);if let http=response as? HTTPURLResponse,!(200...299).contains(http.statusCode){try? FileManager.default.removeItem(at:temp);failures+=1;continue};let size=(try? FileManager.default.attributesOfItem(atPath:temp.path)[.size] as? NSNumber)?.int64Value ?? 0;if size>500*1024*1024{try? FileManager.default.removeItem(at:temp);failures+=1;continue};let filename=response.suggestedFilename ?? url.lastPathComponent;let safe=URL(fileURLWithPath:filename.isEmpty ? "downloaded-media" : filename).lastPathComponent;let dest=directory.appendingPathComponent(UUID().uuidString+"-"+safe);try FileManager.default.moveItem(at:temp,to:dest);files.append(dest.path);downloaded+=1}catch{failures+=1}};for membership in memberships where !db.collections.contains(where:{$0.caseInsensitiveCompare(membership) == .orderedSame}){db.collections.append(membership)};let key=collectionTrigger(rawKey,collection:group);db.clips.insert(Clip(key:key,name:name,text:phrase,group:group,files:files,directMediaPaste:!files.isEmpty,groups:memberships.count>1 ? memberships:nil),at:0);count += 1}
  notice="Imported \(count) shortcuts · \(downloaded) media downloaded"+(failures>0 ? " · \(failures) download(s) failed":"")
 }
}

