  VStack(alignment:.leading,spacing:15){
   Label(hasPasscode ? "Unlock Private Mode":"Set up Private Mode",systemImage:"lock.shield.fill").font(.title2.bold()).foregroundStyle(.purple)
   Text(hasPasscode ? "Enter your six-digit passcode to open your saved private links, collections, and tabs.":"Choose a six-digit passcode. Your private browser workspace will be encrypted and saved on this Mac.").foregroundStyle(.secondary)
   SecureField("Six-digit passcode",text:$pin).textFieldStyle(.roundedBorder).onChange(of:pin){_,value in pin=String(value.filter(\.isNumber).prefix(6))}
   if !hasPasscode{SecureField("Confirm passcode",text:$confirmation).textFieldStyle(.roundedBorder).onChange(of:confirmation){_,value in confirmation=String(value.filter(\.isNumber).prefix(6))}}
   if !error.isEmpty{Text(error).font(.caption).foregroundStyle(.red)}
   HStack{Spacer();Button("Cancel"){dismiss()};Button(hasPasscode ? "Unlock":"Create passcode"){if onUnlock(pin,hasPasscode ? nil:confirmation){dismiss()}else{error=pin.count != 6 ? "Enter all six digits.":(!hasPasscode && pin != confirmation ? "The passcodes do not match.":"That passcode did not unlock the private workspace.")}}.buttonStyle(.borderedProminent).tint(.purple).disabled(pin.count != 6 || (!hasPasscode && confirmation.count != 6))}
  }.padding(22).frame(width:410)
 }
