 @ViewBuilder private func mediaThumbnail(_ url:URL)->some View{if isVideo(url){Image(systemName:"play.rectangle.fill").font(.title2).foregroundStyle(.purple).frame(maxWidth:.infinity,maxHeight:.infinity).background(Color.purple.opacity(0.1))}else if let image=NSImage(contentsOf:url){Image(nsImage:image).resizable().scaledToFill()}else{Image(systemName:"photo").foregroundStyle(.secondary)}}
 private func isVideo(_ url:URL)->Bool{["mp4","mov","m4v","avi","webm","mpeg","mpg"].contains(url.pathExtension.lowercased())}
 private func isGIF(_ url:URL)->Bool{url.pathExtension.lowercased()=="gif"}
 private func isImage(_ url:URL)->Bool{["png","jpg","jpeg","webp","tif","tiff","bmp","heic","heif"].contains(url.pathExtension.lowercased())}
 private func matchesFilter(_ url:URL)->Bool{mediaTypeFilter=="All" || (mediaTypeFilter=="Videos" && isVideo(url)) || (mediaTypeFilter=="Images" && isImage(url)) || (mediaTypeFilter=="GIFs" && isGIF(url))}
 private func loadByMediaName(){let query=mediaSearch.trimmingCharacters(in:.whitespacesAndNewlines);guard !query.isEmpty else{return};if let match=(loadedClips.flatMap{$0.files}+clips.flatMap{$0.files}).first(where:{let url=URL(fileURLWithPath:$0);return url.lastPathComponent.localizedCaseInsensitiveContains(query) && matchesFilter(url) && FileManager.default.fileExists(atPath:$0)}){let url=URL(fileURLWithPath:match);if let clip=clips.first(where:{$0.files.contains(match)}),!loadedClips.contains(where:{$0.id==clip.id}){loadedClips.append(clip)};selectMedia(url);message="Loaded \(url.lastPathComponent)."}else{message="No matching shortcut media filename contains ‘\(query)’ yet. Load a matching shortcut or import the file."}}
