 private func loadShortcut(_ clip:Clip){let paths=clip.files.filter{let url=URL(fileURLWithPath:$0);return FileManager.default.fileExists(atPath:$0) && matchesFilter(url)};guard !paths.isEmpty else{message="\(displayTrigger(clip.key)) has no available \(mediaTypeFilter.lowercased()) media files.";return};var filtered=clip;filtered.files=paths;if !loadedClips.contains(where:{$0.id==clip.id}){loadedClips.append(filtered)};if let url=paths.map({URL(fileURLWithPath:$0)}).first(where:isVideo) ?? paths.first.map(URL.init(fileURLWithPath:)){selectMedia(url)};message="Loaded \(paths.count) media item(s) from \(displayTrigger(clip.key))."}
 private func loadTypedShortcuts(){let matches=matchedClips;if matches.isEmpty{mediaSearch=command;loadByMediaName();return};let filtered=matches.compactMap{clip -> Clip? in var copy=clip;copy.files=clip.files.filter{let url=URL(fileURLWithPath:$0);return FileManager.default.fileExists(atPath:$0) && matchesFilter(url)};return copy.files.isEmpty ? nil:copy};guard !filtered.isEmpty else{message="Those shortcuts have no media matching the selected type.";return};loadedClips=filtered;let urls=filtered.flatMap{$0.files}.map{URL(fileURLWithPath:$0)};if let first=urls.first(where:isVideo) ?? urls.first{selectMedia(first)};message="Loaded \(urls.count) media item(s) from \(filtered.count) shortcut(s)."}
