 private func selectMedia(_ url:URL){sourceURL=url;outputPreview=false;outputPaths=[];outputName=url.deletingPathExtension().lastPathComponent+" cut";let safe=outputName.lowercased().replacingOccurrences(of:"[^a-z0-9]+",with:"-",options:.regularExpression).trimmingCharacters(in:CharacterSet(charactersIn:"-"));outputShortcut=String((safe.isEmpty ? "cut":safe).prefix(20));if isVideo(url){let asset=AVURLAsset(url:url);let seconds=asset.duration.seconds;duration=seconds.isFinite ? seconds:0;start=0;end=duration;player=AVPlayer(url:url);player?.pause()}else{duration=0;player=nil}}
