 private func applyFont(_ transform:(NSFont)->NSFont){
  guard let textView else{return}
  let range=textView.selectedRange()
  if range.length==0{let old=textView.typingAttributes[.font] as? NSFont ?? textView.font ?? NSFont.systemFont(ofSize:14);textView.typingAttributes[.font]=transform(old);return}
  guard let storage=textView.textStorage else{return}
