  storage.enumerateAttribute(.font,in:range,options:[]){value,subrange,_ in
   let font=value as? NSFont ?? NSFont.systemFont(ofSize:14)
   updates.append((subrange,transform(font)))
  }
  storage.beginEditing();for(update,font)in updates{storage.addAttribute(.font,value:font,range:update)};storage.endEditing();textView.setSelectedRange(range);textView.didChangeText()
 }
