 private let variableTypeChoices=["Number","Currency","Date","String","Percentage"]
 private func variableType(at index:Int)->String{variableTypes.indices.contains(index) ? variableTypes[index]:"String"}
 private var variableTypeDescription:String{variableList.enumerated().map{"\($0.element): \(variableType(at:$0.offset))"}.joined(separator:", ")}
 private func setVariableType(_ type:String,at index:Int){while variableTypes.count<=index{variableTypes.append("String")};variableTypes[index]=type;persistConfiguration()}
 private func variableExamplePlaceholder(_ type:String)->String{switch type{case "Number":return "Example · 12";case "Currency":return "Example · 25000";case "Date":return "Example · 2026-11-05";case "Percentage":return "Example · 18%";default:return "Example · text"}}
