   ScrollView {
    VStack(alignment:.leading,spacing:13) {
     appHeader
     ForEach(setupTabs,id:\.self) { item in
      DisclosureGroup(isExpanded:Binding(get:{expandedBuilderSections.contains(item)},set:{expanded in if expanded{expandedBuilderSections.insert(item);selectedSetupTab=item}else{expandedBuilderSections.remove(item)}})) {
