        if item=="Information" && !variableList.isEmpty{Text("\(variableList.count) inputs").font(.caption.weight(.semibold)).foregroundStyle(.black.opacity(0.75))}
        if item=="Template"{Text(outputFormat.uppercased()).font(.caption2.bold()).foregroundStyle(.red).padding(.horizontal,8).padding(.vertical,4).background(Color.red.opacity(0.08),in:Capsule())}
       }.padding(.vertical,5)
      }
      .padding(13).background(Color.white.opacity(0.88),in:RoundedRectangle(cornerRadius:15)).overlay(RoundedRectangle(cornerRadius:15).stroke(Color.purple.opacity(expandedBuilderSections.contains(item) ? 0.35:0.13),lineWidth:expandedBuilderSections.contains(item) ? 1.4:1))
