 private func setupPage(_ item:String)->some View {
  Group {switch item{case "Action":actionSetup;case "Collection":collectionsConfiguration;case "Information":variablesConfiguration;case "Formula":formulaConfiguration;default:templateDesignStep}}
 }
 private func moveSetupTab(_ direction:Int) {
  guard let index=setupTabs.firstIndex(of:selectedSetupTab) else { return }
  selectedSetupTab=setupTabs[min(setupTabs.count-1,max(0,index+direction))]
 }
