 private func makeExternalAIPrompt()->String{
  let records=previewSourceRecords
  let collectionText=records.map{clip in
   var block="• \(displayTrigger(clip.key)) — \(clip.name) [\(clip.allGroups.joined(separator:", "))]"
   let body=clip.text.trimmingCharacters(in:.whitespacesAndNewlines)
   if !body.isEmpty{block += "\n  Expanded information: \(body)"}
   if !clip.files.isEmpty{block += "\n  Reference media: \(clip.files.map{URL(fileURLWithPath:$0).lastPathComponent}.joined(separator:", "))\n  Attach with EzMe command: \(displayTrigger(clip.key))"}
   return block
  }.joined(separator:"\n")
  let collections=selectedCollections.sorted().map{collection in "\(collection) (command alias: \(collectionValues[collection] ?? "not set"))"}.joined(separator:"\n")
  let inputs=variableList.enumerated().map{index,field in let value=(inputValues[field] ?? "").trimmingCharacters(in:.whitespacesAndNewlines);return "• \(field) [\(variableType(at:index))]: \(value.isEmpty ? "NOT PROVIDED — ask for it; never guess":"\(value)")"}.joined(separator:"\n")
  let templateBody=prompt.trimmingCharacters(in:.whitespacesAndNewlines)
  let formula=formulaRules.trimmingCharacters(in:.whitespacesAndNewlines)
  let mediaCommands=records.filter{!$0.files.isEmpty}.map{displayTrigger($0.key)}
  var result="Create the requested \(outputFormat) output. Return the finished deliverable only, with no explanation.\n\nACTION\nName: \(name)\nAction code: \\\(shortcutPrefix.isEmpty ? name.lowercased():shortcutPrefix)\nPurpose and instructions: \(UserDefaults.standard.string(forKey:"ezmeBuilderDescription."+name) ?? UserDefaults.standard.string(forKey:"ezmeBuilderPrompt."+name) ?? "Use the action name and template below.")\n\nCOLLECTIONS AND EXPANDED SHORTCUT INFORMATION\n\(collections.isEmpty ? "No source collections selected.":collections)\n\(collectionText.isEmpty ? "No shortcuts selected yet.":collectionText)\n\nMISSING INFORMATION / VARIABLES\n\(inputs.isEmpty ? "No variable inputs configured.":inputs)\n\nFORMULAS\n\(formula.isEmpty ? "No calculated fields configured.":formula)\nExample values for preview only: \(formulaPreview)\n\nOUTPUT TEMPLATE\nFormat: \(outputFormat)\nStyle: \(templateStyle)\nTemplate text: \(templateBody.isEmpty ? "Create a clean, polished template using only the configured information.":templateBody)\nFixed brand details: \(predefinedDetails.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty ? "None":predefinedDetails)\nTypography: bold=\(templateBold), italic=\(templateItalic), underline=\(templateUnderline), size=\(Int(templateFontSize)) pt, colour=\(templateFontColor)."
  if !referenceTemplatePaths.isEmpty{result += "\nVisual reference templates (use as layout/style references only): \(referenceTemplatePaths.map{URL(fileURLWithPath:$0).lastPathComponent}.joined(separator:", "))."}
  if !assetPath.isEmpty{result += "\nBrand asset to attach separately: \(URL(fileURLWithPath:assetPath).lastPathComponent)."}
  if !mediaCommands.isEmpty{result += "\n\nREFERENCE MEDIA ATTACHMENTS\nAfter pasting this prompt into the AI composer, invoke these EzMe shortcuts there as separate attachments: \(mediaCommands.joined(separator:", ")). Use the actual uploaded media as visual references; do not treat the command text as content."}
  result += "\n\nRULES\nUse only the supplied collection records, entered variables, configured formulas, and fixed details. Do not invent names, dates, amounts, contact information, or facts. If a required value is marked NOT PROVIDED, ask for it before creating the final output. Preserve the template’s purpose and create a readable, professional result."
  return result
 }
