 private func formulaBlockTitle(_ token:String)->String {
  if token.hasPrefix("Action: "){return "Action · "+token.replacingOccurrences(of:"Action: ",with:"")}
  if token.hasPrefix("Collection: "){let value=token.replacingOccurrences(of:"Collection: ",with:"");let index=(selectedCollections.sorted().firstIndex(of:value) ?? 0)+1;return "Collection \(index) · "+value}
  return "Variable · "+token.replacingOccurrences(of:"Variable: ",with:"")
 }
 private func moveFormulaBlock(_ items:[String],to index:Int)->Bool {
  guard let moving=items.first,let from=formulaOrder.firstIndex(of:moving),formulaOrder.indices.contains(index)else{return false}
  formulaOrder.move(fromOffsets:IndexSet(integer:from),toOffset:index>from ? index+1:index)
  persistFormulaOrder()
  return true
 }
 private func replaceCollectionBlock(at index:Int,with collection:String){guard formulaOrder.indices.contains(index),tokenCollection(formulaOrder[index]) != nil else{return};let old=tokenCollection(formulaOrder[index])!;selectedCollections.remove(old);selectedCollections.insert(collection);formulaOrder[index]="Collection: "+collection;collectionsText=selectedCollections.sorted().joined(separator:", ");persistFormulaOrder()}
 private func tokenCollection(_ token:String)->String?{token.hasPrefix("Collection: ") ? String(token.dropFirst("Collection: ".count)):nil}
 private func removeFormulaBlock(at index:Int){guard formulaOrder.indices.contains(index)else{return};formulaOrder.remove(at:index);persistFormulaOrder()}
 private func addFormulaBlocks(_ items:[String])->Bool {
  var changed=false
  for token in items where formulaTokens.contains(token) && !formulaOrder.contains(token){formulaOrder.append(token);changed=true}
  if changed{persistFormulaOrder()}
  return changed
 }
