 private func createActionFromPrompt() {
  let title=newActionName.trimmingCharacters(in:.whitespacesAndNewlines),description=newActionPrompt.trimmingCharacters(in:.whitespacesAndNewlines)
  guard !title.isEmpty else{status="Give the action a short name first.";return}
  let safeCode=String(title.lowercased().replacingOccurrences(of:"[^a-z0-9]+",with:"-",options:.regularExpression).trimmingCharacters(in:CharacterSet(charactersIn:"-")).prefix(14))
  UserDefaults.standard.set(description,forKey:"ezmeBuilderPrompt."+title)
  UserDefaults.standard.set(description,forKey:"ezmeBuilderDescription."+title)
  UserDefaults.standard.set(safeCode,forKey:"ezmeBuilderPrefix."+title)
  if UserDefaults.standard.string(forKey:"ezmeBuilderVariables."+title)==nil{UserDefaults.standard.set("",forKey:"ezmeBuilderVariables."+title)}
  if UserDefaults.standard.string(forKey:"ezmeBuilderCollections."+title)==nil{UserDefaults.standard.set("",forKey:"ezmeBuilderCollections."+title)}
  if UserDefaults.standard.string(forKey:"ezmeBuilderOutputCollections."+title)==nil{UserDefaults.standard.set("",forKey:"ezmeBuilderOutputCollections."+title)}
  if UserDefaults.standard.string(forKey:"ezmeBuilderFormat."+title)==nil{UserDefaults.standard.set(outputFormat,forKey:"ezmeBuilderFormat."+title)}
  if UserDefaults.standard.string(forKey:"ezmeBuilderTemplate."+title)==nil{UserDefaults.standard.set("Blank",forKey:"ezmeBuilderTemplate."+title)}
  onCreateAction(title)
 }

