 private static func limitTemplateLines(_ text:String,to maximum:Int)->String{let clean=text.replacingOccurrences(of:"```[a-zA-Z]*",with:"",options:.regularExpression);let lines=clean.components(separatedBy:.newlines).map{$0.trimmingCharacters(in:.whitespacesAndNewlines)}.filter{!$0.isEmpty}.prefix(maximum);return lines.map{line in let words=line.split(whereSeparator:\.isWhitespace);return words.prefix(18).joined(separator:" ")}.filter{!$0.isEmpty}.joined(separator:"\n")}
 private func restrictTemplateTokens(_ text:String)->String{
  var allowed=Set<String>()
  for variable in variableList{allowed.insert(variable.lowercased().replacingOccurrences(of:"[^a-z0-9]+",with:"",options:.regularExpression))}
  for calculated in builderCalculationNames(formulaRules){allowed.insert(calculated)}
  for index in orderedFormulaTokens.filter({$0.hasPrefix("Collection: ")}).indices{allowed.insert("collection\(index+1)")}
  for token in ["details","collections","date","time","datetime","timestamp","weekday","month","year","unix","uuid","clipboard"]{allowed.insert(token)}
  guard let regex=try? NSRegularExpression(pattern:#"\{\{([^}]+)\}\}"#)else{return text}
  let ns=text as NSString;var result=text
  for match in regex.matches(in:text,range:NSRange(location:0,length:ns.length)).reversed(){
   let raw=ns.substring(with:match.range(at:1))
   let normalized=raw.lowercased().replacingOccurrences(of:"[^a-z0-9]+",with:"",options:.regularExpression)
   if !allowed.contains(normalized) && !raw.lowercased().hasPrefix("worldclock:"){
    let staticLabel=raw.split(whereSeparator:{ !$0.isLetter && !$0.isNumber }).map(String.init).joined(separator:" ").capitalized
    result=(result as NSString).replacingCharacters(in:match.range,with:staticLabel)
   }
  }
  let fieldAliases=Dictionary(uniqueKeysWithValues:variableList.map{field in (field.lowercased().replacingOccurrences(of:"[^a-z0-9]+",with:"",options:.regularExpression),field.lowercased().replacingOccurrences(of:"[^a-z0-9]+",with:"",options:.regularExpression))})
  if let brackets=try? NSRegularExpression(pattern:#"\[([^\]]+)\]"#){let current=result as NSString;for match in brackets.matches(in:result,range:NSRange(location:0,length:current.length)).reversed(){let raw=current.substring(with:match.range(at:1));let key=raw.lowercased().replacingOccurrences(of:"[^a-z0-9]+",with:"",options:.regularExpression);let replacement:String;if let alias=fieldAliases[key]{replacement="{{\(alias)}}"}else if ["date","time","datetime","weekday","month","year","unix","uuid","clipboard"].contains(key){replacement="{{\(key)}}"}else{replacement=""};result=(result as NSString).replacingCharacters(in:match.range,with:replacement)}}
  return result
 }
