 private func invalidTemplateTokens(_ source:String)->[String]{
  guard let regex=try? NSRegularExpression(pattern:#"\{\{([^}]+)\}\}"#)else{return []}
  let ns=source as NSString
  var allowed=Set(variableList.map{$0.lowercased().replacingOccurrences(of:"[^a-z0-9]+",with:"",options:.regularExpression)})
  for calculated in builderCalculationNames(formulaRules){allowed.insert(calculated)}
  for index in orderedFormulaTokens.filter({$0.hasPrefix("Collection: ")}).indices{allowed.insert("collection\(index+1)")}
  for token in ["details","collections","date","time","datetime","timestamp","weekday","month","year","unix","uuid","clipboard"]{allowed.insert(token)}
  return regex.matches(in:source,range:NSRange(location:0,length:ns.length)).compactMap{match in
   let raw=ns.substring(with:match.range(at:1));let key=raw.lowercased().replacingOccurrences(of:"[^a-z0-9]+",with:"",options:.regularExpression)
   return allowed.contains(key) || raw.lowercased().hasPrefix("worldclock:") ? nil:raw
  }
 }
 private func resolvedCollectionValue(_ collection:String,index:Int,clips:[Clip])->String{
  let picked=clips.filter{$0.allGroups.contains(where:{$0.caseInsensitiveCompare(collection) == .orderedSame})}
  if !picked.isEmpty{return picked.map{clip in let media=clip.files.isEmpty ? "":" [attached media: \(clip.files.map{URL(fileURLWithPath:$0).lastPathComponent}.joined(separator:", "))]";return "\(clip.name): \(clip.text)\(media)"}.joined(separator:"\n")}
  let raw=(collectionValues[collection] ?? "").trimmingCharacters(in:.whitespacesAndNewlines);guard !raw.isEmpty else{return raw}
  let match=clips.first{$0.allGroups.contains(where:{$0.caseInsensitiveCompare(collection) == .orderedSame}) && ($0.key.localizedCaseInsensitiveContains(raw) || $0.name.localizedCaseInsensitiveContains(raw) || $0.text.localizedCaseInsensitiveContains(raw))}
  return match.map{"\(raw) — \($0.name): \($0.text)"} ?? raw
 }
 private func templateValueMap(chosen:[Clip])->[String:String]{var values=inputValues;let computed=resolveBuilderCalculations(formulaRules,values:values);values=computed.values;for(index,token) in orderedFormulaTokens.filter({$0.hasPrefix("Collection: ")}).enumerated(){let collection=String(token.dropFirst("Collection: ".count));values["collection\(index+1)"]=resolvedCollectionValue(collection,index:index,clips:chosen)};return values}
 private var shortcutKey:String{let entries=orderedFormulaTokens.compactMap{token -> String? in if let group=tokenCollection(token){return collectionValues[group]};if token.hasPrefix("Variable: "){return inputValues[String(token.dropFirst("Variable: ".count))]};return nil}.compactMap{$0.trimmingCharacters(in:.whitespacesAndNewlines)};let tail=entries.map{$0.replacingOccurrences(of:"[^A-Za-z0-9]+",with:"-",options:.regularExpression)}.joined(separator:"-");return String(([shortcutPrefix]+(tail.isEmpty ? []:[tail])).filter{!$0.isEmpty}.joined(separator:"-").prefix(40))}
 private func generate() async {
  busy = true
  status = "Generating output…"
  output = ""
  outputPath = ""
  defer { busy = false }

  let chosen = previewSourceRecords
  let context = chosen.map { "\($0.key) — \($0.name): \($0.text)" }.joined(separator: "\n")
  var outputRich:NSAttributedString?
  do {
   if outputFormat == "Image" {
    guard let profile=imageModelProfile else{status="Add an OpenAI or Gemini image-generation profile in API configuration.";return}
    let imageKey=KeyStore.load(account:profile.keyAccount) ?? ""
    guard !imageKey.isEmpty else{status="Add an API key for \(profile.name) in API configuration to generate images.";return}
    let values=templateValueMap(chosen:chosen);let imagePrompt=renderLocalTemplate(effectiveOutputPrompt,predefinedDetails:predefinedDetails,context:context,values:values)
    let bytes=try await BuilderMediaGenerator.generateImage(provider:profile.provider,key:imageKey,modelID:imageModelID,prompt:imagePrompt,referencePaths:selectedImageReferences,aspectRatio:mediaAspectRatio,resolution:imageResolution)
    output="Generated image · \(imagePrompt)";outputPath=try saveGeneratedMedia(bytes,extension:"png")
   } else if outputFormat == "Video" {
    guard selectedModel.provider.lowercased().contains("google") || selectedModel.provider.lowercased().contains("gemini") else{status="Choose a Google Gemini model profile for video generation. Video API access can require a paid Google AI plan.";return}
    let values=templateValueMap(chosen:chosen);let videoPrompt=renderLocalTemplate(effectiveOutputPrompt,predefinedDetails:predefinedDetails,context:context,values:values)
    status="Generating video with \(videoModelID)… this can take a few minutes."
    let bytes=try await BuilderMediaGenerator.generateVideo(modelID:videoModelID,key:apiKey,prompt:videoPrompt,referencePaths:selectedImageReferences,aspectRatio:mediaAspectRatio)
    output="Generated video · \(videoPrompt)";outputPath=try saveGeneratedMedia(bytes,extension:"mp4")
   } else if outputFormat == "HTML" && !effectiveOutputPrompt.contains("{{") {
    let values=(selectedCollections.sorted().enumerated().map{index,collection in "Collection \(index+1) (\(collection)): \(resolvedCollectionValue(collection,index:index,clips:chosen))"}+variableList.map{"Variable \($0): \(inputValues[$0] ?? "")"}).joined(separator:"\n")
    let instruction="Create a complete, responsive, accessible HTML page for \(name). Return only a standalone HTML document with embedded CSS and no markdown fences. Use the supplied information accurately and do not invent facts.\n\nPage requirements:\n\(effectiveOutputPrompt)\n\nFixed brand details:\n\(predefinedDetails)\n\nSaved collection records:\n\(context)\n\nUser variables:\n\(values)\n\nCalculated values:\n\(resolveBuilderCalculations(formulaRules,values:inputValues).summary)"
    output=try await SharedAIClient.generate(profile:selectedModel,key:apiKey,prompt:instruction,maxTokens:7000).trimmingCharacters(in:.whitespacesAndNewlines)
   } else if prompt.contains("{{") {
    let invalid=invalidTemplateTokens(prompt);if !invalid.isEmpty{status="Template has fields outside your configured inputs: \(invalid.joined(separator:", ")). Remove them or set the matching input count.";return}
    let template=TemplateRichEditorController.attributed(templateRTFData) ?? NSAttributedString(string:prompt,attributes:[.font:NSFont.systemFont(ofSize:14)]);outputRich=renderAttributedTemplate(template,predefinedDetails:predefinedDetails,context:context,values:templateValueMap(chosen:chosen));output=outputRich?.string ?? expandLiveTemplateTokens(renderLocalTemplate(prompt, predefinedDetails: predefinedDetails, context: context, values:templateValueMap(chosen:chosen)))
   } else {
    let values=(selectedCollections.sorted().enumerated().map{index,collection in "Collection \(index+1) (\(collection)): \(resolvedCollectionValue(collection,index:index,clips:chosen))"}+variableList.map{"Variable \($0): \(inputValues[$0] ?? "")"}).joined(separator:"\n")
    let calculations=resolveBuilderCalculations(formulaRules,values:inputValues).summary
    let instruction="Action: \(name)\nInstructions: \(effectiveOutputPrompt)\nPredefined details: \(predefinedDetails)\nSelected collection records:\n\(context)\nVariable details:\n\(values)\nCalculated values:\n\(calculations)\nReturn only the final finished output. Use only supplied data; do not invent missing facts."
    output=try await SharedAIClient.generate(profile:selectedModel,key:apiKey,prompt:instruction,maxTokens:6000).trimmingCharacters(in:.whitespacesAndNewlines)
   }
   guard !output.isEmpty else { status = "The result is empty. Check the prompt, variables, and template fields."; return }
   if outputFormat == "PDF" {
    let directory = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0].appendingPathComponent("MiniJ/AIOutputs", isDirectory: true)
    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
    let file = directory.appendingPathComponent(shortcutKey + "-" + String(UUID().uuidString.prefix(6)) + ".pdf")
    let data=AITextPDFCanvas.makePDF(title:name,text:output,assetPath:assetPath,templateStyle:templateStyle,details:predefinedDetails,fontSize:CGFloat(templateFontSize),bold:templateBold,italic:templateItalic,underline:templateUnderline,fontColor:templateFontColor,richText:outputRich)
    try data.write(to:file,options:.atomic)
    outputPath = file.path
   } else if outputFormat == "HTML" {
    output=makeStandaloneHTML(output,title:name,accent:templateStyle)
    outputPath=try saveGeneratedMedia(Data(output.utf8),extension:"html")
   }
   status = "Output ready. Review it before saving or sharing."
  } catch {
   status = "Could not generate the output: \(error.localizedDescription)"
  }
 }
 private func saveGeneratedMedia(_ data:Data,extension ext:String)throws->String{let directory=attachmentDirectory.appendingPathComponent("Generated",isDirectory:true);try FileManager.default.createDirectory(at:directory,withIntermediateDirectories:true);let url=directory.appendingPathComponent(name.replacingOccurrences(of:"[^A-Za-z0-9_-]+",with:"-",options:.regularExpression)+"-"+String(UUID().uuidString.prefix(8))+"."+ext);try data.write(to:url,options:.atomic);return url.path}
 private func makeStandaloneHTML(_ source:String,title:String,accent:String)->String{let trimmed=source.trimmingCharacters(in:.whitespacesAndNewlines);if trimmed.range(of:"<html",options:.caseInsensitive) != nil || trimmed.range(of:"<!doctype",options:.caseInsensitive) != nil{return trimmed};let safe=trimmed.replacingOccurrences(of:"&",with:"&amp;").replacingOccurrences(of:"<",with:"&lt;").replacingOccurrences(of:">",with:"&gt;");let color=accent=="Bill" || accent=="Quotation" ? "#6828d9":"#5421a8";return "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>\(title)</title><style>body{font:16px/1.65 -apple-system,BlinkMacSystemFont,sans-serif;color:#242033;margin:0;background:#f7f4ff}.page{max-width:900px;margin:40px auto;padding:40px;background:#fff;border-radius:20px;box-shadow:0 12px 40px #28135a18}h1{color:\(color)}pre{white-space:pre-wrap;font:inherit}@media(max-width:650px){.page{margin:12px;padding:20px}}</style></head><body><main class=\"page\"><h1>\(title)</h1><pre>\(safe)</pre></main></body></html>"}
}

private struct OutputFilePreview:View{let url:URL;var body:some View{Group{if url.pathExtension.lowercased()=="pdf"{PDFKitPreview(url:url)}else if url.pathExtension.lowercased()=="html"{HTMLFilePreview(url:url)}else if url.pathExtension.lowercased()=="mp4"{VideoFilePreview(url:url)}else if let image=NSImage(contentsOf:url){ScrollView([.vertical,.horizontal]){Image(nsImage:image).resizable().scaledToFit().padding(14)}}else{ContentUnavailableView("Preview unavailable",systemImage:"doc.questionmark",description:Text("The output file could not be opened."))}}.frame(minWidth:760,minHeight:620).navigationTitle(url.lastPathComponent)}}
private struct HTMLFilePreview:NSViewRepresentable{let url:URL;func makeNSView(context:Context)->WKWebView{let view=WKWebView();view.loadFileURL(url,allowingReadAccessTo:url.deletingLastPathComponent());return view};func updateNSView(_ view:WKWebView,context:Context){}}
private struct VideoFilePreview:NSViewRepresentable{let url:URL;func makeNSView(context:Context)->AVPlayerView{let view=AVPlayerView();view.controlsStyle = .default;view.player=AVPlayer(url:url);view.player?.play();return view};func updateNSView(_ view:AVPlayerView,context:Context){if view.player?.currentItem?.asset is AVURLAsset == false{view.player=AVPlayer(url:url)}}}
private struct PDFKitPreview:NSViewRepresentable{let url:URL;func makeNSView(context:Context)->PDFView{let view=PDFView();view.autoScales=true;view.displayMode = .singlePageContinuous;view.displayDirection = .vertical;view.document=PDFDocument(url:url);return view};func updateNSView(_ view:PDFView,context:Context){if view.document?.documentURL != url{view.document=PDFDocument(url:url)}}}
private struct CollectionMultiSelectDropdown:View{
 var title:String;var options:[String];@Binding var selection:Set<String>;var onCreate:(String)->Void;var onOpenBuilder:()->Void = {}
