struct MediaPreview:View{
 let path:String
 @State private var player:AVPlayer?
 @State private var isHovering=false
 @State private var pointerInside=false
 @State private var dismissWork:DispatchWorkItem?
 private var ext:String{URL(fileURLWithPath:path).pathExtension.lowercased()}
 private var isImage:Bool{["png","jpg","jpeg","gif","webp","tif","tiff","bmp","heic","heif"].contains(ext)}
 private var isVideo:Bool{["mp4","mov","m4v","avi","webm","mpeg","mpg"].contains(ext)}
 var body:some View{ZStack(alignment:.topLeading){thumbnail; if isHovering{expandedPreview.onHover{updateHover($0)}.offset(x:48,y:-18).zIndex(50)}}.frame(maxWidth:.infinity,maxHeight:.infinity).onHover{updateHover($0)}.onDisappear{dismissWork?.cancel();player?.pause()}.zIndex(isHovering ? 100:0)}
 @ViewBuilder private var thumbnail:some View{if isImage,let image=NSImage(contentsOfFile:path){Image(nsImage:image).resizable().scaledToFit().frame(maxWidth:.infinity,maxHeight:.infinity).background(Color.black.opacity(0.05),in:RoundedRectangle(cornerRadius:7)).overlay(RoundedRectangle(cornerRadius:7).stroke(.quaternary))}else{ZStack{RoundedRectangle(cornerRadius:7).fill((isVideo ? Color.blue:Color.orange).opacity(0.10));Image(systemName:isVideo ? "play.rectangle.fill":(isAudio ? "waveform":"doc.fill")).font(.system(size:18,weight:.medium)).foregroundStyle(isVideo ? .blue:.orange);if isVideo{Image(systemName:"play.fill").font(.system(size:8)).foregroundStyle(.white).padding(5).background(Color.blue,in:Circle()).offset(x:12,y:12)}}}}
 @ViewBuilder private var expandedPreview:some View{VStack(spacing:0){if isImage,let image=NSImage(contentsOfFile:path){Image(nsImage:image).resizable().scaledToFit().frame(width:370,height:270).background(Color.black.opacity(0.92))}else if isVideo{if let player{VideoPlayer(player:player).frame(width:370,height:270).background(Color.black)}else{ProgressView().frame(width:370,height:270)}}else{VStack(spacing:12){Image(systemName:isAudio ? "waveform":"doc.fill").font(.system(size:42)).foregroundStyle(.orange);Text(URL(fileURLWithPath:path).lastPathComponent).font(.subheadline).lineLimit(2)}.frame(width:370,height:270)}}.overlay(alignment:.bottomLeading){Text(URL(fileURLWithPath:path).lastPathComponent).font(.caption.weight(.medium)).lineLimit(1).padding(8).frame(maxWidth:.infinity,alignment:.leading).background(.ultraThinMaterial)}.clipShape(RoundedRectangle(cornerRadius:12)).overlay(RoundedRectangle(cornerRadius:12).stroke(Color.black.opacity(0.25),lineWidth:1)).shadow(color:.black.opacity(0.28),radius:18,y:8).background(.regularMaterial,in:RoundedRectangle(cornerRadius:12))}
 private var isAudio:Bool{["mp3","wav","m4a","aac","flac","aiff","ogg"].contains(ext)}
 private func updateHover(_ inside:Bool){pointerInside=inside;dismissWork?.cancel();if inside{isHovering=true;if isVideo,player==nil{let value=AVPlayer(url:URL(fileURLWithPath:path));player=value;DispatchQueue.main.asyncAfter(deadline:.now()+0.15){if pointerInside{value.play()}}}}else{let work=DispatchWorkItem{if !pointerInside{isHovering=false;player?.pause()}};dismissWork=work;DispatchQueue.main.asyncAfter(deadline:.now()+0.3,execute:work)}}
}
