private struct LoopingVideoCover:NSViewRepresentable{
 let url:URL
 final class Coordinator{var url:URL?;var player:AVQueuePlayer?;var looper:AVPlayerLooper?;func stop(){player?.pause();player=nil;looper=nil}}
 func makeCoordinator()->Coordinator{Coordinator()}
 func makeNSView(context:Context)->LoopingCoverContainer{let view=LoopingCoverContainer();start(in:view,coordinator:context.coordinator);return view}
 func updateNSView(_ view:LoopingCoverContainer,context:Context){if context.coordinator.url != url{context.coordinator.stop();start(in:view,coordinator:context.coordinator)}}
 static func dismantleNSView(_ view:LoopingCoverContainer,coordinator:Coordinator){coordinator.stop()}
 private func start(in view:LoopingCoverContainer,coordinator:Coordinator){guard FileManager.default.fileExists(atPath:url.path)else{return};let player=AVQueuePlayer();player.isMuted=true;let item=AVPlayerItem(url:url);coordinator.url=url;coordinator.player=player;coordinator.looper=AVPlayerLooper(player:player,templateItem:item);view.player=player;player.play()}
}
