@MainActor struct BulkShortcutRenameSheet:View{
 @Environment(\.dismiss)private var dismiss
 var clips:[Clip];var allKeys:[String];var onApply:([UUID:(key:String,name:String)])->Void
 @State private var target="Shortcut codes";@State private var mode="Add prefix";@State private var findText="";@State private var replacement="";@State private var error=""
 private let modes=["Add prefix","Add suffix","Replace prefix","Replace suffix","Find & replace","Lowercase","UPPERCASE","Title Case","Use shortcut name"]
 var body:some View{VStack(alignment:.leading,spacing:15){Text("Bulk rename shortcuts").font(.system(size:23,weight:.bold,design:.rounded));Text("Apply one rename rule to all \(clips.count) selected shortcuts. Shortcut codes keep their slash and file-type suffix.").foregroundStyle(.secondary).fixedSize(horizontal:false,vertical:true);Picker("Rename",selection:$target){Text("Shortcut codes").tag("Shortcut codes");Text("Shortcut names").tag("Shortcut names");Text("Codes and names").tag("Codes and names")}.pickerStyle(.segmented);Picker("Action",selection:$mode){ForEach(modes,id:\.self){Text($0).tag($0)}}.pickerStyle(.menu);if ["Add prefix","Add suffix","Replace prefix","Replace suffix","Find & replace"].contains(mode){TextField(mode=="Add prefix" ? "Prefix to add":(mode=="Add suffix" ? "Suffix to add":(mode=="Replace prefix" ? "Existing prefix":(mode=="Replace suffix" ? "Existing suffix":"Text to find"))),text:$findText).textFieldStyle(.roundedBorder);if ["Replace prefix","Replace suffix","Find & replace"].contains(mode){TextField("Replace with",text:$replacement).textFieldStyle(.roundedBorder)}};if target != "Shortcut codes"{Text("Name changes affect only the displayed shortcut name; they do not alter the expansion text or attachments.").font(.caption).foregroundStyle(.secondary)};if mode=="Use shortcut name" && target=="Shortcut names"{Text("Choose Shortcut codes or Codes and names to create codes from each shortcut’s current name.").font(.caption).foregroundStyle(.orange)};if !error.isEmpty{Text(error).font(.caption).foregroundStyle(.red).fixedSize(horizontal:false,vertical:true)};HStack{Spacer();Button("Cancel"){dismiss()};Button("Apply to \(clips.count)"){apply()}.buttonStyle(.borderedProminent).disabled(clips.isEmpty || (["Add prefix","Add suffix","Replace prefix","Replace suffix","Find & replace"].contains(mode) && findText.isEmpty))}}.padding(24).frame(width:520).onAppear{error=""}}
 private func transformed(_ value:String)->String{switch mode{case "Add prefix":return findText+value;case "Add suffix":return value+findText;case "Replace prefix":return value.hasPrefix(findText) ? replacement+value.dropFirst(findText.count):value;case "Replace suffix":return value.hasSuffix(findText) ? String(value.dropLast(findText.count))+replacement:value;case "Find & replace":return value.replacingOccurrences(of:findText,with:replacement,options:.caseInsensitive);case "Lowercase":return value.lowercased();case "UPPERCASE":return value.uppercased();case "Title Case":return value.capitalized;default:return value}}
 private func transformedCode(_ clip:Clip)->String{var raw=clip.key.trimmingCharacters(in:CharacterSet(charactersIn:"/\\"));let suffixes=[".media",".app",".ai",".web",".gif",".e"];let suffix=suffixes.first(where:{raw.lowercased().hasSuffix($0)}) ?? "";if !suffix.isEmpty{raw=String(raw.dropLast(suffix.count))};let result:String;if mode=="Use shortcut name"{result=clip.name.lowercased().replacingOccurrences(of:"[^a-z0-9]+",with:"-",options:.regularExpression).trimmingCharacters(in:CharacterSet(charactersIn:"-"))}else{result=transformed(raw).lowercased().replacingOccurrences(of:"[\\s/\\\\]+",with:"-",options:.regularExpression)};return "/"+result+suffix}
 private func apply(){error="";var changes=[UUID:(key:String,name:String)]();for clip in clips{let changeCode=target != "Shortcut names";let changeName=target != "Shortcut codes" && mode != "Use shortcut name";let key=changeCode ? transformedCode(clip):clip.key;let name=changeName ? transformed(clip.name):clip.name;guard !key.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty,key.count<=48 else{error="A resulting shortcut code is empty or longer than 48 characters. Shorten the added text and try again.";return};changes[clip.id]=(key,name)};var occupied=Set(allKeys.filter{key in !clips.contains(where:{$0.key.caseInsensitiveCompare(key) == .orderedSame})}.map{$0.lowercased()});for value in changes.values{guard occupied.insert(value.key.lowercased()).inserted else{error="This rename would create a duplicate shortcut code (\(value.key)). Change the rule or selection and try again.";return}};onApply(changes);dismiss()}
}

