struct EditSheet: View {
    @Environment(\.dismiss) var dismiss
    var item: Clip?
    var collections:[String]
    var attachmentDirectory:URL
    var defaultGroup:String=""
    var onOpenBuilder:()->Void = {}
    var save: (Clip) -> Void
    @State var key = ""
    @State var name = ""
    @State var text = ""
    @State private var webURL = ""
    @State var group = ""
    @State private var additionalGroups=Set<String>()
    @State var files: [String] = []
    @State var directMediaPaste = false
    @State var mediaURL = ""
    @State var downloadingURL = false
    @State var mediaNotice = ""
    @State private var collectionManuallySelected=false
    var body: some View {
        VStack(spacing: 0) {
            ScrollView {
                VStack(alignment: .leading, spacing: 14) {
                    Text(item == nil ? "New shortcut" : "Edit shortcut").font(.title2.bold())
                    Text("Add a phrase, link, instruction, or media attachment. Media-only shortcuts are available from the backslash popup.").foregroundStyle(.secondary)
                    TextField("Shortcut · e.g. \\thanks", text: $key)
                    TextField("Shortcut name", text: $name)
                    if item?.webURL != nil { TextField("Website URL",text:$webURL) }
                    Text("EXPANDS TO").font(.caption.bold()).foregroundStyle(.secondary)
                    TextEditor(text: $text).frame(minHeight: 100, maxHeight: 150).overlay(RoundedRectangle(cornerRadius: 8).stroke(.quaternary))
                    Text("INSERT LIVE VALUE").font(.caption.bold()).foregroundStyle(.secondary)
                    HStack{tokenButton("Date","{{date}}");tokenButton("Time","{{time}}");tokenButton("Weekday","{{weekday}}");tokenButton("World clock","{{worldclock:Asia/Kolkata}}")}.buttonStyle(.bordered).controlSize(.small)
                    HStack{tokenButton("Month","{{month}}");tokenButton("Year","{{year}}");tokenButton("Unix time","{{unix}}");tokenButton("UUID","{{uuid}}");tokenButton("Clipboard","{{clipboard}}")}.buttonStyle(.bordered).controlSize(.small)
                    Picker("Primary collection", selection: $group) { Text("Choose collection (optional)").tag(""); ForEach(collections, id: \.self) { Text($0).tag($0) } }.onChange(of:group){_ in collectionManuallySelected=true;additionalGroups.remove(group)}
                    Text(group.isEmpty ? "No collection selected? This shortcut will be saved in Imported only.":"Also assign it to more collections if needed.").font(.caption).foregroundStyle(.secondary)
                    CollectionMultiSelectDropdown(title:additionalGroups.isEmpty ? "Also in collections (optional)":"Also in \(additionalGroups.count) more collection(s)",options:collections.filter{$0.caseInsensitiveCompare(group) != .orderedSame},selection:$additionalGroups,onCreate:{_ in},onOpenBuilder:onOpenBuilder).controlSize(.large)
                    HStack{Button("＋ Attach images, audio, video, or files") { attach() }.disabled(files.count >= 10);Text("\(files.count)/10").font(.caption).foregroundStyle(.secondary)}
                    HStack{TextField("Paste media URL",text:$mediaURL);Button(downloadingURL ? "Downloading…":"Download & attach"){Task{await downloadMediaURL()}}.disabled(mediaURL.isEmpty || files.count >= 10 || downloadingURL)}
                    if !mediaNotice.isEmpty{Text(mediaNotice).font(.caption).foregroundStyle(.secondary)}
                    if !files.isEmpty {
                        Toggle("Paste attached media directly when this shortcut is selected", isOn: $directMediaPaste).font(.subheadline)
                        ScrollView(.horizontal) {
                            HStack(alignment: .top, spacing: 12) {
                                ForEach(files, id: \.self) { path in
                                    VStack(alignment: .leading, spacing: 5) {
                                        MediaPreview(path: path).frame(width: 150, height: 105).clipShape(RoundedRectangle(cornerRadius: 8))
                                        Text(URL(fileURLWithPath: path).lastPathComponent).font(.caption).lineLimit(1).frame(width: 150, alignment: .leading)
                                        Button("Remove") { files.removeAll { $0 == path } }.font(.caption).foregroundStyle(.red)
                                    }
                                }
                            }
                        }.frame(height: 160)
                    }
                }.padding(24)
            }
            Divider()
            HStack {
                Spacer()
                Button("Cancel") { dismiss() }
                Button("Save shortcut") {
                    let selectedGroup=group.isEmpty ? "Imported":group
                    let memberships=[selectedGroup]+collections.filter{additionalGroups.contains($0)}
                    let newClip = Clip(id: item?.id ?? UUID(), key: collectionTrigger(key,collection:selectedGroup), name: name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? collectionTrigger(key,collection:selectedGroup) : name.trimmingCharacters(in: .whitespacesAndNewlines), text: text, group: selectedGroup, files: files, directMediaPaste: directMediaPaste,groups:memberships.count>1 ? memberships:nil,appBundleIdentifier:item?.appBundleIdentifier,appPath:item?.appPath,webURL:webURL.isEmpty ? item?.webURL:webURL,defaultMediaArticle:item?.defaultMediaArticle)
                    save(newClip)
                    dismiss()
                }.buttonStyle(.borderedProminent).tint(Color.green).disabled(key.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty || (text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty && files.isEmpty))
            }.padding(16)
        }
        .textFieldStyle(.roundedBorder).frame(width: 560, height: 570)
        .onAppear { if let i = item { key = displayTrigger(i.key); name = i.name; text = i.text; webURL=i.webURL ?? ""; group = i.group; additionalGroups=Set(i.allGroups.filter{$0.caseInsensitiveCompare(i.group) != .orderedSame});files = i.files; directMediaPaste = i.directMediaPaste ?? false;collectionManuallySelected=true }else{group=defaultGroup} }
    }
    func tokenButton(_ title:String,_ token:String)->some View{Button(title){if !text.isEmpty && !text.hasSuffix(" "){text += " "};text += token+" "}}
    @MainActor func downloadMediaURL() async {guard let url=URL(string:mediaURL),["http","https"].contains(url.scheme?.lowercased() ?? "") else{mediaNotice="Enter a valid http or https URL.";return};downloadingURL=true;mediaNotice="Downloading media into EzMe…";defer{downloadingURL=false};do{var request=URLRequest(url:url);request.timeoutInterval=120;let(temp,response)=try await URLSession.shared.download(for:request);if response.expectedContentLength > 500*1024*1024{try? FileManager.default.removeItem(at:temp);mediaNotice="That file is over the 500 MB limit.";return};let suggested=response.suggestedFilename ?? url.lastPathComponent;let clean=suggested.isEmpty ? "downloaded-media" : suggested;let dir=attachmentDirectory;try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true);let dest=dir.appendingPathComponent(UUID().uuidString+"-"+clean);try FileManager.default.moveItem(at:temp,to:dest);files.append(dest.path);mediaURL="";mediaNotice="Downloaded and attached: \(clean)"}catch{mediaNotice="Download failed: \(error.localizedDescription)"}}
    func attach() {
        let p = NSOpenPanel(); p.allowedContentTypes = [.image, .movie, .audio, .pdf, .data]; p.allowsMultipleSelection = true
        if p.runModal() == .OK {
            let d = attachmentDirectory
            try? FileManager.default.createDirectory(at: d, withIntermediateDirectories: true)
            for u in p.urls.prefix(max(0,10-files.count)) { let x = d.appendingPathComponent(UUID().uuidString + "-" + u.lastPathComponent); try? FileManager.default.copyItem(at: u, to: x); files.append(x.path) }
        }
    }
}
