private struct PromptShortcutExpansion{var text:String;var paths:[String];var labels:[String]}
private func expandPromptShortcutMentions(_ source:String,clips:[Clip],records:[CollectionRecord])->PromptShortcutExpansion{
    struct Entry{var token:String;var label:String;var expansion:String;var paths:[String]}
    var entries=[Entry]()
    for clip in clips where !clip.key.isEmpty {
        let alias=promptCanonicalAlias(clip.key);guard !alias.isEmpty else{continue}
        let body=promptExpandTokens(clip.text).trimmingCharacters(in:.whitespacesAndNewlines)
        entries.append(Entry(token:alias,label:clip.name,expansion:"Saved shortcut · \(clip.name):\n\(body.isEmpty ? "(Use the attached media reference.)":body)",paths:clip.files))
    }
    for record in records {
        let alias=promptCanonicalAlias(record.alias);guard !alias.isEmpty else{continue}
        let body=record.values.sorted{$0.key<$1.key}.map{"\($0.key): \(promptExpandTokens($0.value))"}.joined(separator:"\n")
        entries.append(Entry(token:alias,label:record.name,expansion:"Saved record · \(record.name):\n\(body.isEmpty ? record.name:body)",paths:record.files))
    }
    // A collection name is also a valid prompt reference. Expand its saved entries
    // together, while keeping media on the prompt's attachment list.
    let collectionNames=Set(clips.flatMap{$0.allGroups}.filter{!$0.isEmpty})
        .union(records.map{$0.collection}.filter{!$0.isEmpty})
    for collection in collectionNames {
        let matchingClips=clips.filter{$0.allGroups.contains(where:{$0.caseInsensitiveCompare(collection) == .orderedSame})}
        let matchingRecords=records.filter{$0.collection.caseInsensitiveCompare(collection) == .orderedSame}
        guard !matchingClips.isEmpty || !matchingRecords.isEmpty else{continue}
        var lines=[String](),paths=[String]()
        for clip in matchingClips.prefix(30) {
            let body=promptExpandTokens(clip.text).trimmingCharacters(in:.whitespacesAndNewlines)
            lines.append("• \\(promptCanonicalAlias(clip.key)): \(clip.name)\(body.isEmpty ? "":" — "+body)")
            for path in clip.files where !paths.contains(path){paths.append(path)}
        }
        for record in matchingRecords.prefix(30) {
            let body=record.values.sorted{$0.key<$1.key}.map{"\($0.key): \(promptExpandTokens($0.value))"}.joined(separator:"; ")
            lines.append("• \\(promptCanonicalAlias(record.alias)): \(record.name)\(body.isEmpty ? "":" — "+body)")
            for path in record.files where !paths.contains(path){paths.append(path)}
        }
        if matchingClips.count+matchingRecords.count>60{lines.append("• (Collection has more entries; showing the first 60.)")}
        entries.append(Entry(token:collection.lowercased(),label:collection,expansion:"Collection · \(collection):\n\(lines.joined(separator:"\n"))",paths:paths))
    }
    // Ambiguous aliases are skipped rather than silently choosing the wrong record.
    let grouped=Dictionary(grouping:entries,by:{$0.token})
    let unique=grouped.values.compactMap{$0.count==1 ? $0[0]:nil}.sorted{$0.token.count>$1.token.count}
    let original=source as NSString
    var replacements=[(NSRange,String,Entry)]()
    for entry in unique {
        let escaped=NSRegularExpression.escapedPattern(for:entry.token)
        let pattern="(?i)(?<![A-Za-z0-9_])(?:\\\\|/)?\(escaped)(?:\\.(?:media|app|ai|web|gif|e))?(?![A-Za-z0-9_])"
        guard let regex=try? NSRegularExpression(pattern:pattern)else{continue}
        for match in regex.matches(in:source,range:NSRange(location:0,length:original.length)) {
            replacements.append((match.range,entry.expansion,entry))
        }
    }
    // Prefer the longest match where collection names and shortcut aliases overlap.
    replacements.sort{$0.0.location == $1.0.location ? $0.0.length>$1.0.length:$0.0.location>$1.0.location}
    var result=source,occupied=[NSRange](),paths=[String](),labels=[String]()
    for (range,replacement,entry) in replacements {
        guard !occupied.contains(where:{occupiedRange in NSIntersectionRange(range,occupiedRange).length>0}) else{continue}
        result=(result as NSString).replacingCharacters(in:range,with:replacement);occupied.append(range)
        for path in entry.paths where !paths.contains(path){paths.append(path)}
        if !labels.contains(entry.label){labels.append(entry.label)}
    }
    return PromptShortcutExpansion(text:result,paths:Array(paths.prefix(10)),labels:labels)
}

private func promptExpandTokens(_ source:String)->String{let pattern="\\{\\{([^}]+)\\}\\}";guard let regex=try? NSRegularExpression(pattern:pattern)else{return source};let ns=source as NSString;var result=source;for match in regex.matches(in:source,range:NSRange(location:0,length:ns.length)).reversed(){let token=ns.substring(with:match.range(at:1));let lower=token.lowercased();let value:String;switch lower{case "date":value=Date.now.formatted(date:.long,time:.omitted);case "time":value=Date.now.formatted(date:.omitted,time:.shortened);case "datetime":value=Date.now.formatted(date:.long,time:.shortened);case "weekday":value=Date.now.formatted(.dateTime.weekday(.wide));case "month":value=Date.now.formatted(.dateTime.month(.wide));case "year":value=Date.now.formatted(.dateTime.year());case "uuid":value=UUID().uuidString;case "clipboard":value=NSPasteboard.general.string(forType:.string) ?? "";default:value="{{\(token)}}"};result=(result as NSString).replacingCharacters(in:match.range,with:value)};return result}
