private func pickerPopupSize(visible:NSRect,areaPercent:Double,aspect:CGFloat=1.55)->NSSize {
    let fraction=min(max(areaPercent,0.08),0.25)
    let area=max(1,visible.width*visible.height*fraction)
    let width=min(sqrt(area*aspect),visible.width,visible.height*aspect)
    return NSSize(width:width,height:min(width/aspect,visible.height))
}

